    for (const body of [{ keep: ['nope'] }, { dry_run: 'yes' }, { keep: [], extra: 1 }]) {
      const rejected = await call('POST', '/cache/gc', body);
      assert.deepEqual({ status: rejected.status, code: rejected.json.error.code }, { status: 400, code: 'validation_error' });
