    assertHex(digest, 'digest');
    return path.join(this.blobRoot, digest.slice(0, 2), digest);
  }

  manifestPath(key) {
    assertHex(key, 'action key');
    return path.join(this.manifestRoot, key.slice(0, 2), `${key}.json`);
  }

  metaPath(...parts) {
    return path.join(this.metaRoot, ...parts);
  }

