  }

  async readMeta(name) {
    try {
      return JSON.parse(await readFile(this.metaPath(name), 'utf8'));
    } catch (error) {
      if (error.code === 'ENOENT') return null;
      throw error;
    }
  }

  async deleteMeta(name) {
    await rm(this.metaPath(name), { force: true });
  }
}

